('22222222-2222-4222-8222-222222222202', '11111111-1111-4111-8111-111111111109', 'Ana G.', 25, 'NONE', 'Playa Norte 100% libre de sargazo! El agua está cristalina como una alberca.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', 21.2611, -86.7517, NOW() - INTERVAL '1 hour'),
('22222222-2222-4222-8222-222222222203', '11111111-1111-4111-8111-111111111114', 'Rodrigo V.', 8, 'MEDIUM', 'Llegada moderada en la orilla de Playa Mamitas. Se puede nadar mar adentro.', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=800&q=80', 20.6322, -87.0631, NOW() - INTERVAL '4 hours'),
('22222222-2222-4222-8222-222222222204', '11111111-1111-4111-8111-111111111122', 'Valeria S.', 15, 'HIGH', 'Calor fuerte y arribazón constante en la orilla. Se recomienda buscar caletas protegidas.', 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?auto=format&fit=crop&w=800&q=80', 20.1983, -87.4300, NOW() - INTERVAL '3 hours'),
